function start(){const s=byId[data.selected],lv=upgradeLevel(s.id);run={time:0,hp:s.hp*(1+.1*lv),maxHp:s.hp*(1+.1*lv),kills:0,spawn:0,shot:0,level:1,xp:0,nextXp:7,damage:s.damage*(1+.05*lv),speed:s.speed,rate:s.rate,projectiles:1,paused:false,ended:false,boss:false,player:{x:400,y:240},enemies:[],shots:[],effects:[],enemyId:0,hit:0};tab='Combate';render();}
function finish(win){if(!run||run.ended)return;run.ended=true;run.paused=false;data.runs++;data.best=Math.max(data.best,run.time);const reward=Math.max(1,Math.floor(run.time/15))+(win?5:0),coins=Math.floor(run.kills/3)+(win?25:0);data.tickets+=reward;data.coins+=coins;save();render();message((win?'¡Victoria!':'Fin de partida')+' · +'+reward+' tickets · +'+coins+' DigiCoins');}
function gainXp(){if(run.paused||run.ended)return;run.xp++;if(run.xp>=run.nextXp){run.xp-=run.nextXp;run.level++;run.nextXp+=5;run.paused=true;const box=$('levelChoices');if(!box){run.paused=false;return;}box.style.display='block';box.innerHTML='<h2>Nivel '+run.level+' · Elige mejora</h2>';for(const [label,fn] of [['+20% daño',()=>run.damage*=1.2],['+15% velocidad',()=>run.speed*=1.15],['+20 HP máximo y curar',()=>{run.maxHp+=20;run.hp=Math.min(run.maxHp,run.hp+30);}],['Ataque más rápido',()=>run.rate*=.88]])box.append(btn(label,()=>{fn();box.style.display='none';run.paused=false;}));}}
function update(dt){if(!run||run.ended||run.paused||tab!=='Combate')return;const r=run,p=r.player;r.time+=dt;r.spawn-=dt;r.shot-=dt;r.hit-=dt;const dx=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft'))+stick.x,dy=Number(keys.has('s')||keys.has('arrowdown'))-Number(keys.has('w')||keys.has('arrowup'))+stick.y,len=Math.max(1,Math.hypot(dx,dy));p.x=Math.max(15,Math.min(785,p.x+dx/len*r.speed*dt));p.y=Math.max(15,Math.min(465,p.y+dy/len*r.speed*dt));if(r.spawn<=0){r.spawn=Math.max(.25,.85-r.time*.004);const side=Math.floor(Math.random()*4);{const type=r.time>35&&Math.random()<.25?'runner':r.time>20&&Math.random()<.3?'tank':'normal';r.enemies.push({x:side===0?0:side===1?800:Math.random()*800,y:side===2?0:side===3?480:Math.random()*480,hp:(2+Math.floor(r.time/35))*(type==='tank'?3:1),boss:false,uid:++r.enemyId,slowUntil:0,type});}}
if(!r.boss&&r.time>=65){r.boss=true;r.enemies.push({x:400,y:0,hp:55,boss:true,maxHp:55,uid:++r.enemyId,slowUntil:0});}
if(r.shot<=0&&r.enemies.length){r.shot=r.rate;const targets=r.enemies.filter(e=>e.hp>0);if(targets.length){const target=targets.reduce((a,b)=>Math.hypot(p.x-a.x,p.y-a.y)<Math.hypot(p.x-b.x,p.y-b.y)?a:b);const angle=Math.atan2(target.y-p.y,target.x-p.x);for(let i=0;i<r.projectiles;i++){const a=angle+(i-(r.projectiles-1)/2)*.17;r.shots.push({...DigimonCombat.projectile(byId[data.selected].element,r.damage,p.x,p.y,a),color:ELEMENT_COLORS[byId[data.selected].element]||'#ffdc64'});}}}
for(const e of r.enemies){const d=Math.max(1,Math.hypot(e.x-p.x,e.y-p.y)),spd=(e.boss?35:e.type==='runner'?105:e.type==='tank'?32:58)*(e.slowUntil>0?.6:1);e.slowUntil=Math.max(0,(e.slowUntil||0)-dt);e.x+=(p.x-e.x)/d*spd*dt;e.y+=(p.y-e.y)/d*spd*dt;if(d<(e.boss?34:21)&&r.hit<=0){r.hp-=e.boss?20:12;r.hit=.5;}}
for(const s of r.shots){s.x+=s.vx*dt;s.y+=s.vy*dt;s.ttl-=dt;for(const e of r.enemies){if(e.hp>0&&Math.hypot(s.x-e.x,s.y-e.y)<(e.boss?33:16)){if(DigimonCombat.applyHit(s,e)){r.effects.push({x:e.x,y:e.y,ttl:.22,color:s.color});if(s.ttl<=0)break;}}}}
const dead=r.enemies.filter(e=>e.hp<=0);r.kills+=dead.length;r.enemies=r.enemies.filter(e=>e.hp>0);r.shots=r.shots.filter(s=>s.ttl>0);for(const fx of r.effects)fx.ttl-=dt;r.effects=r.effects.filter(fx=>fx.ttl>0);for(const e of dead){if(!r.paused)gainXp();else r.xp++;}if(r.hp<=0){r.hp=0;finish(false);}else if(r.boss&&!r.enemies.some(e=>e.boss)){finish(true);}else if(r.time>=90){finish(false);}}
function draw(){if(tab!=='Combate'||!$('game')||!run)return;const ctx=$('game').getContext('2d'),r=run,p=r.player;ctx.clearRect(0,0,800,480);ctx.fillStyle='#25404a';ctx.strokeStyle='#35505a';for(let x=0;x<800;x+=40)for(let y=0;y<480;y+=40)ctx.strokeRect(x,y,40,40);for(const e of r.enemies){ctx.fillStyle=e.boss?'#9f4ccf':e.type==='runner'?'#fbbf24':e.type==='tank'?'#64748b':'#ef6d75';ctx.beginPath();ctx.arc(e.x,e.y,e.boss?30:e.type==='tank'?17:e.type==='runner'?8:11,0,Math.PI*2);ctx.fill();if(e.boss){ctx.fillStyle='#101827';ctx.fillRect(e.x-34,e.y-45,68,7);ctx.fillStyle='#f59e0b';ctx.fillRect(e.x-33,e.y-44,66*Math.max(0,e.hp/e.maxHp),5);}}for(const s of r.shots){ctx.fillStyle=s.color;ctx.beginPath();ctx.arc(s.x,s.y,5,0,Math.PI*2);ctx.fill();}for(const fx of r.effects){ctx.strokeStyle=fx.color;ctx.lineWidth=3;ctx.beginPath();ctx.arc(fx.x,fx.y,5+(1-fx.ttl/.22)*18,0,Math.PI*2);ctx.stroke();}ctx.fillStyle=byId[data.selected].color;ctx.save();ctx.translate(p.x,p.y);ctx.rotate(Math.sin(r.time*5)*.07);ctx.beginPath();ctx.moveTo(0,-17);ctx.lineTo(15,12);ctx.lineTo(-15,12);ctx.closePath();ctx.fill();ctx.restore();ctx.fillStyle='white';ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText(byId[data.selected].name,p.x,p.y-23);$('runHud').textContent='HP '+Math.ceil(r.hp)+'/'+Math.ceil(r.maxHp)+' · KOs '+r.kills+' · Nivel '+r.level+' · '+Math.floor(r.time)+'/90s'+(r.boss?' · JEFE':'')+(r.paused?' · PAUSA':'');}
